import os, glob, re

def load_grids():
    d = os.environ['RLM_SESSION_DIR']
    session_dir = os.path.basename(d)
    log_path = os.path.join(d, '..', 'sessions', session_dir + '.jsonl')
    try:
        with open(log_path) as f:
            content = f.read()
    except:
        return {}

    G = {}
    for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = match[1], int(match[2]), int(match[3])
        rows = [r.split() for r in content[match.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_grids()
print("Grids found:", sorted(G.keys()))
for k, v in G.items():
    print(f"{k}: {len(v)}x{len(v[0]) if v else 0}")

